#!/usr/bin/env bash
# bash completion support for swamp

_swamp() {
  local word cur prev listFiles
  local -a opts
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"
  cmd="_"
  opts=()
  listFiles=0

  _swamp_complete() {
    local action="$1"; shift
    mapfile -t values < <( swamp completions complete "${action}" "${@}" )
    for i in "${values[@]}"; do
      opts+=("$i")
    done
  }

  _swamp_expand() {
    [ "$cur" != "${cur%\\}" ] && cur="$cur\\"

    # expand ~username type directory specifications
    if [[ "$cur" == \~*/* ]]; then
      # shellcheck disable=SC2086
      eval cur=$cur

    elif [[ "$cur" == \~* ]]; then
      cur=${cur#\~}
      # shellcheck disable=SC2086,SC2207
      COMPREPLY=( $( compgen -P '~' -u $cur ) )
      return ${#COMPREPLY[@]}
    fi
  }

  # shellcheck disable=SC2120
  _swamp_file_dir() {
    listFiles=1
    local IFS=$'\t\n' xspec #glob
    _swamp_expand || return 0

    if [ "${1:-}" = -d ]; then
      # shellcheck disable=SC2206,SC2207,SC2086
      COMPREPLY=( ${COMPREPLY[@]:-} $( compgen -d -- $cur ) )
      #eval "$glob"    # restore glob setting.
      return 0
    fi

    xspec=${1:+"!*.$1"}	# set only if glob passed in as $1
    # shellcheck disable=SC2206,SC2207
    COMPREPLY=( ${COMPREPLY[@]:-} $( compgen -f -X "$xspec" -- "$cur" )           $( compgen -d -- "$cur" ) )
  }

  __swamp() {
    opts=(--json --log --log-level -q --quiet -v --verbose --no-telemetry --show-properties --no-color behavior)

    if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
      return 0
    fi
    case "${prev}" in
      --json)  ;;
      --log)  ;;
      --log-level) opts=(); _swamp_complete string ;;
      -q|--quiet)  ;;
      -v|--verbose)  ;;
      --no-telemetry)  ;;
      --show-properties)  ;;
      --no-color)  ;;
    esac
  }

  __swamp_behavior() {
    opts=(--json --log --log-level -q --quiet -v --verbose --no-telemetry --show-properties --no-color run create get edit delete validate evaluate search cancel describe history output type)

    if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
      return 0
    fi
    case "${prev}" in
      --json)  ;;
      --log)  ;;
      --log-level) opts=(); _swamp_complete string behavior ;;
      -q|--quiet)  ;;
      -v|--verbose)  ;;
      --no-telemetry)  ;;
      --show-properties)  ;;
      --no-color)  ;;
    esac
  }

  __swamp_behavior_run() {
