      --report) opts=(); _swamp_complete string behavior run ;;
      --report-label) opts=(); _swamp_complete string behavior run ;;
      --timeout) opts=(); _swamp_complete string behavior run ;;
      --server) opts=(); _swamp_complete string behavior run ;;
      --token) opts=(); _swamp_complete string behavior run ;;
      --token-file) opts=(); _swamp_complete string behavior run ;;
      --ca-cert) opts=(); _swamp_complete string behavior run ;;
