  if [[ listFiles -eq 1 ]]; then
    return 0
  fi

  if [[ ${#opts[@]} -eq 0 ]]; then
    # shellcheck disable=SC2207
    COMPREPLY=($(compgen -f "${cur}"))
    return 0
  fi

  local values
  values="$( printf "\n%s" "${opts[@]}" )"
  local IFS=$'\n'
  # shellcheck disable=SC2207
  local result=($(compgen -W "${values[@]}" -- "${cur}"))
  if [[ ${#result[@]} -eq 0 ]]; then
    # shellcheck disable=SC2207
    COMPREPLY=($(compgen -f "${cur}"))
  else
    # shellcheck disable=SC2207
    COMPREPLY=($(printf '%q\n' "${result[@]}"))
  fi

  return 0
}

