    '(--server)'--server'[Run through a '"'"'swamp serve'"'"' server (ws:// or http://) instead of locally; no local repo required (env: SWAMP_SERVE_URL or SWAMP_SERVER_URL). For proxy/tunnel pass-through headers see SWAMP_SERVE_EXTRA_HEADERS.]:url:->url-string' \
    '(--token)'--token'[Server token in <name>.<secret> format; only applies with --server (overrides stored credentials and SWAMP_SERVER_TOKEN)]:token:->token-string' \
    '(--token-file)'--token-file'[Path to a file containing the server token; mutually exclusive with --token (env: SWAMP_SERVER_TOKEN_FILE)]:path:->path-string' \
    '(--ca-cert)'--ca-cert'[Path to PEM-encoded CA certificate to trust for TLS connections to the server (env: SWAMP_CA_CERT)]:path:->path-string' \
    '1:command:_commands'

  case "$state" in
    level-string) __swamp_complete level string behavior type search ;;
    dir-string) __swamp_complete dir string behavior type search ;;
    url-string) __swamp_complete url string behavior type search ;;
    token-string) __swamp_complete token string behavior type search ;;
    path-string) __swamp_complete path string behavior type search ;;
  esac
}

# shellcheck disable=SC2154
if [ "${funcstack[1]}" = "_swamp" ]; then
  _swamp "${@}"
else
  compdef _swamp swamp;
fi
